const BG="#FFF8F0",CARD="#FFFFFF",BDR="#F0D9C0",CREAM="#3D1A00",MUT="#8B5E3C",GOLD="#E8821A",LIGHT="#FDE8CC",SUCCESS="#2D7A3A",ERROR="#C0392B",DARK="#3D1A00";

export default function ClientOrderForm(){
  const [step,setStep]=useState(1);
  const [lang,setLang]=useState("AR");
  const lookupRef=React.useRef(0);
  const [dataChanged,setDataChanged]=useState(false);
  const [dataSaved,setDataSaved]=useState(false);
  const [saving,setSaving]=useState(false);
  const [prefix,setPrefix]=useState("");
  const [name,setName]=useState("");
  const [phone,setPhone]=useState("");
  const [delivery,setDelivery]=useState("delivery");
  const [gov,setGov]=useState("");
  const [area,setArea]=useState("");
  const [customGov,setCustomGov]=useState("");
  const [propType,setPropType]=useState("apt");
  const [building,setBuilding]=useState("");
  const [aptNum,setAptNum]=useState("");
  const [floor,setFloor]=useState("");
  const [street,setStreet]=useState("");
  const [extra,setExtra]=useState("");
  const [mapOpen,setMapOpen]=useState(false);
  const [locSet,setLocSet]=useState(false);
  const [lat,setLat]=useState(null);
  const [lng,setLng]=useState(null);
  const [items,setItems]=useState({});
  const [mapsLink,setMapsLink]=useState("");
  const [isCompound,setIsCompound]=useState(false);
  const [compoundName,setCompoundName]=useState("");
  const [notes,setNotes]=useState("");
  const [errors,setErrors]=useState({});
  const [sent,setSent]=useState(false);
  const [memberId,setMemberId]=useState(null);
  const [isExisting,setIsExisting]=useState(false);
  const [lookingUp,setLookingUp]=useState(false);

  // Normalize phone for comparison
  // Save updated client data
  const saveClientData=async()=>{
    setSaving(true);
    try{
      const r=await fetch(`${FIREBASE_URL}/db.json`);
      const db=await r.json()||{};
      const clients=db.clients||[];
      const norm=normalizePhone(phone);
      const exists=clients.find(c=>normalizePhone(c.phone)===norm||c.memberId===memberId);
      const updatedClients=exists
        ?clients.map(c=>normalizePhone(c.phone)===norm||c.memberId===memberId?{...c,name,prefix,phone}:c)
        :[...clients,{id:"C-"+Date.now(),memberId,name,prefix,phone,joinedAt:Date.now(),totalOrders:0,totalSpent:0}];
      await fetch(`${FIREBASE_URL}/db.json`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({clients:updatedClients})});
      setDataChanged(false);setDataSaved(true);
    }catch{}
    setSaving(false);
  };

  // Lookup by member ID
  const handleMemberId=async(val)=>{
    if(val.length<5) return;
    setLookingUp(true);
    try{
      const r=await fetch(`${FIREBASE_URL}/db.json`);
      const db=await r.json()||{};
      const clients=db.clients||[];
      const dbOrdersRaw=db.orders||{};
      const dbOrders=Array.isArray(dbOrdersRaw)?dbOrdersRaw:Object.values(dbOrdersRaw);
      const rootRes=await fetch(`${FIREBASE_URL}/orders.json`);
      const rootRaw=await rootRes.json()||{};
      const rootOrders=Array.isArray(rootRaw)?rootRaw:Object.values(rootRaw);
      const allOrders=[...dbOrders,...rootOrders].filter(o=>o&&o.phone).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
      const found=clients.find(c=>c.memberId?.toUpperCase()===val.toUpperCase());
      const prevOrder=allOrders.find(o=>o.memberId?.toUpperCase()===val.toUpperCase());
      if(found||prevOrder){
        const cData=found||{};const oData=prevOrder||{};
        if(cData.phone||oData.phone) setPhone(cData.phone||oData.phone||"");
        setName(cData.name||oData.client||oData.name||"");
        if(cData.prefix||oData.prefix) setPrefix(cData.prefix||oData.prefix||"");
        if(oData.gov){setGov(oData.gov);setArea(oData.area||"");}
        if(oData.building) setBuilding(oData.building||"");
        if(oData.aptNum) setAptNum(oData.aptNum||"");
        if(oData.floor) setFloor(oData.floor||"");
        if(oData.street) setStreet(oData.street||"");
        if(oData.extra) setExtra(oData.extra||"");
        setMemberId(cData.memberId||oData.memberId||val);
        setIsExisting(true);
      }else{setIsExisting(false);setName("");setMemberId(null);}
    }catch{setIsExisting(false);}
    setLookingUp(false);
  };

  const normalizePhone=p=>(p||"").replace(/[\s\-\+]/g,"").replace(/^0020/,"0").replace(/^20/,"0");

  // Auto-fill from phone number
  const handlePhone=async(val)=>{
    setPhone(val);
    const norm=normalizePhone(val);
    const myId=++lookupRef.current; // Track this specific lookup

    if(norm.length>=10){
      setLookingUp(true);
      try{
        const r=await fetch(`${FIREBASE_URL}/db.json`);
        const db=await r.json()||{};

        // If a newer lookup started while we were waiting — discard this result
        if(myId!==lookupRef.current){setLookingUp(false);return;}

        const clients=db.clients||[];
        const dbOrdersRaw=db.orders||{};
        const dbOrders=Array.isArray(dbOrdersRaw)?dbOrdersRaw:Object.values(dbOrdersRaw);
        const rootRes=await fetch(`${FIREBASE_URL}/orders.json`);
        const rootRaw=await rootRes.json()||{};
        const rootOrders=Array.isArray(rootRaw)?rootRaw:Object.values(rootRaw);

        // Check again after second fetch
        if(myId!==lookupRef.current){setLookingUp(false);return;}

        const orders=[...dbOrders,...rootOrders].filter(o=>o&&o.phone).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));

        const found=clients.find(c=>normalizePhone(c.phone)===norm);

        // Search orders more thoroughly — by phone in both locations
        const prevOrder=orders.find(o=>normalizePhone(o.phone)===norm)
          || orders.find(o=>o.memberId&&found&&o.memberId===found.memberId);

        if(found||prevOrder){
          const cData=found||{};
          const oData=prevOrder||{};

          // Name: try client first, then order fields
          const autoName=cData.name||oData.client||oData.name||"";
          setName(autoName);
          if(cData.prefix||oData.prefix) setPrefix(cData.prefix||oData.prefix||"");

          // Address: first try client record, then fall back to most recent order
          const addrSrc = (cData.gov ? cData : null) || oData;
          if(addrSrc.gov)    {setGov(addrSrc.gov);     setArea(addrSrc.area||"");}
          if(addrSrc.building){setBuilding(addrSrc.building||"");}
          if(addrSrc.aptNum)  {setAptNum(addrSrc.aptNum||"");}
          if(addrSrc.floor)   {setFloor(addrSrc.floor||"");}
          if(addrSrc.street)  {setStreet(addrSrc.street||"");}
          if(addrSrc.extra)   {setExtra(addrSrc.extra||"");}
          if(addrSrc.propType){setPropType(addrSrc.propType||"apt");}

          let mId=cData.memberId||null;
          if(!mId){
            // Atomic counter using Firebase ETag (prevents duplicate IDs even with concurrent users)
            let retries=3;
            while(retries>0){
              try{
                // 1. Read counter with ETag
                const cRes=await fetch(`${FIREBASE_URL}/db/memberCounter.json`,{
                  headers:{"X-Firebase-ETag":"true"}
                });
                const currentVal=await cRes.json();
                const etag=cRes.headers.get("ETag");
                const nextVal=(currentVal||0)+1;
                // 2. Write new counter value atomically — fails if someone else changed it
                const putRes=await fetch(`${FIREBASE_URL}/db/memberCounter.json`,{
                  method:"PUT",
                  headers:{"Content-Type":"application/json","If-Match":etag||"*"},
                  body:JSON.stringify(nextVal)
                });
                if(putRes.status===412){
                  // Another client grabbed this number — retry
                  retries--;
                  await new Promise(r=>setTimeout(r,200+Math.random()*300));
                  continue;
                }
                mId=`MBR-${String(nextVal).padStart(3,"0")}`;
                break;
              }catch{retries--;await new Promise(r=>setTimeout(r,300));}
            }
            if(!mId) mId=`MBR-T${Date.now().toString(36).toUpperCase()}`;
            const upd=found
              ?clients.map(c=>normalizePhone(c.phone)===norm?{...c,memberId:mId,name:autoName||c.name}:c)
              :[...clients,{id:"C-"+Date.now(),memberId:mId,name:autoName,phone:val,joinedAt:Date.now(),totalOrders:0,totalSpent:0}];
            await fetch(`${FIREBASE_URL}/db.json`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({clients:upd})});
          }
          setMemberId(mId);
          setIsExisting(true);
        }else{
          // Only update state if this is still the latest lookup
          if(myId!==lookupRef.current){setLookingUp(false);return;}
          // New client — generate unique sequential ID using Firebase atomic counter
          try{
            let retries=3;
            let newMId=null;
            while(retries>0){
              const cRes=await fetch(`${FIREBASE_URL}/db/memberCounter.json`,{headers:{"X-Firebase-ETag":"true"}});
              const currentVal=await cRes.json();
              const etag=cRes.headers.get("ETag");
              const nextVal=(currentVal||0)+1;
              const putRes=await fetch(`${FIREBASE_URL}/db/memberCounter.json`,{
                method:"PUT",
                headers:{"Content-Type":"application/json","If-Match":etag||"*"},
                body:JSON.stringify(nextVal)
              });
              if(putRes.status===412){retries--;await new Promise(r=>setTimeout(r,200+Math.random()*300));continue;}
              newMId=`MBR-${String(nextVal).padStart(3,"0")}`;
              break;
            }
            setMemberId(newMId||`MBR-T${Date.now().toString(36).toUpperCase()}`);
          }catch{
            setMemberId(`MBR-T${Date.now().toString(36).toUpperCase()}`);
          }
          setIsExisting(false);
          setName("");
        }
      }catch{
        setMemberId(`MBR-${String(Date.now()).slice(-3)}`);
        setIsExisting(false);
      }
      setLookingUp(false);
    }else{
      // Only reset if no newer lookup is pending
      if(myId===lookupRef.current){
        setMemberId(null);
        setIsExisting(false);
        setName("");
        setLookingUp(false);
      }
    }
  };

  // ── Load prices from Firebase ──────────────────────────────
  const [products,setProducts]=useState(PRODUCTS);
  useEffect(()=>{
    fetch(`${FIREBASE_URL}/db.json`)
      .then(r=>r.json())
      .then(db=>{
        if(!db) return;
        const cycle=db.cycle||1;
        const cyclePrices=db.pricesByCycle?.[`cycle-${cycle}`]||db.prices||{};
        const enabled=db.productEnabled||{};
        // Show ALL products — mark disabled ones (client sees them but can't order)
        let filtered=PRODUCTS.map(p=>({...p,enabled:enabled[p.id]!==false}));
        if(Object.keys(cyclePrices).length>0){
          filtered=filtered.map(p=>{
            if(!cyclePrices[p.id]) return p;
            const newPrice=cyclePrices[p.id];
            if(p.byWeight) return{...p,pricePerKg:newPrice,price:Math.round(newPrice*CHICKEN_AVG_WEIGHT)};
            return{...p,price:newPrice};
          });
        }
        setProducts(filtered);
      })
      .catch(()=>{});
  },[]);

  useEffect(()=>{
    if(mapOpen){
      if(!window.L){
        const link=document.createElement('link');
        link.rel='stylesheet';
        link.href='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css';
        document.head.appendChild(link);
        const script=document.createElement('script');
        script.src='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js';
        script.onload=initMap;
        document.head.appendChild(script);
      } else { initMap(); }
    }
    if(!mapOpen&&window._cMap){window._cMap.remove();window._cMap=null;}
    if(mapOpen&&window._cMap) setTimeout(()=>window._cMap.invalidateSize(),200);
  },[mapOpen]);

  const initMap=()=>{
    setTimeout(()=>{
      const el=document.getElementById('client-map');
      if(!el||window._cMap) return;
      window._cMap=window.L.map('client-map').setView([30.0444,31.2357],13);
      window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(window._cMap);
      const icon=window.L.divIcon({html:'<div style="font-size:32px;margin-top:-32px;margin-left:-10px">📍</div>',iconSize:[20,32],className:''});
      window._cMarker=window.L.marker([30.0444,31.2357],{draggable:true,icon}).addTo(window._cMap);
      window._cMap.on('click',e=>{window._cMarker.setLatLng(e.latlng);setLat(e.latlng.lat);setLng(e.latlng.lng);setLocSet(true);});
      window._cMarker.on('dragend',e=>{const ll=e.target.getLatLng();setLat(ll.lat);setLng(ll.lng);setLocSet(true);});
    },300);
  };

  const getUserLoc=()=>{
    if(navigator.geolocation){
      navigator.geolocation.getCurrentPosition(pos=>{
        setLat(pos.coords.latitude);setLng(pos.coords.longitude);setLocSet(true);
        if(window._cMap){window._cMap.setView([pos.coords.latitude,pos.coords.longitude],16);window._cMarker.setLatLng([pos.coords.latitude,pos.coords.longitude]);}
      },()=>{});
    }
  };

  const add=id=>setItems(p=>({...p,[id]:(p[id]||0)+1}));
  const rem=id=>setItems(p=>{const n={...p};if(n[id]>1)n[id]--;else delete n[id];return n;});
  const total=Object.entries(items).reduce((s,[id,q])=>{
    const p=products.find(x=>x.id===id);
    if(!p) return s;
    // For weight-based products use estimated price (pricePerKg × avgWeight)
    const unitPrice=p.byWeight?Math.round((p.pricePerKg||CHICKEN_PRICE_PER_KG)*CHICKEN_AVG_WEIGHT):p.price;
    return s+(unitPrice*q);
  },0);
  const hasItems=Object.values(items).some(q=>q>0);

  const t=TRANS[lang];
  const inp=(field)=>({width:"100%",background:CARD,border:`1.5px solid ${errors[field]?ERROR:BDR}`,borderRadius:12,padding:"13px 14px",color:CREAM,fontSize:14,fontFamily:"'Cairo',sans-serif",direction:"rtl",boxSizing:"border-box",outline:"none",boxShadow:errors[field]?`0 0 0 3px rgba(192,57,43,.1)`:"none"});
  const lbl={display:"block",fontSize:12,color:GOLD,marginBottom:5,fontWeight:800};

  const validatePhone=phone=>{
    const cleaned=phone.replace(/\s/g,"");
    return /^01[0125][0-9]{8}$/.test(cleaned);
  };

  const validateStep1=()=>{
    const e={};
    if(!isExisting&&!name.trim())e.name=true;
    if(!phone.trim()||!validatePhone(phone))e.phone=true;
    setErrors(e);
    return Object.keys(e).length===0;
  };

  const validateStep2=()=>{
    if(delivery==="pickup"||!delivery) return true;
    const e={};
    if(!gov)e.gov=true;
    if(!area)e.area=true;
    if(!building.trim())e.building=true;
    if(!aptNum.trim())e.aptNum=true;
    if(isCompound&&!compoundName.trim())e.compoundName=true;
    if(!street.trim()&&!isCompound)e.street=true;
    setErrors(e);
    return Object.keys(e).length===0;
  };

  const validateStep3=()=>{
    if(!hasItems){setErrors({items:true});return false;}
    return true;
  };

  const [sending,setSending]=useState(false);

  const sendOrder=async()=>{
    setSending(true);
    const fullName=`${prefix?prefix+" ":""}${name}`.trim();
    const fullAddress=delivery==="pickup"?"استلام شخصي":`${gov==="أخرى"?customGov:gov} — ${area}${isCompound&&compoundName?" — كومباوند "+compoundName:""}${street?" — "+street:""}${building?" — رقم "+building:""}${aptNum?" ش"+aptNum:""}${floor?" د"+floor:""}${extra?" — "+extra:""}`;
    const orderId="ORD-"+Date.now();
    const order={
      id:orderId,client:fullName,phone,address:fullAddress,
      memberId:memberId||null,
      gov,area,street,building,aptNum,floor,delivery,isCompound,compoundName,items,total,
      notes:"",mapsLink:mapsLink||null,lat:lat||null,lng:lng||null,
      status:"جديد",createdAt:Date.now(),source:"client-app",
    };

    let saved=false;
    try{
      // First read current DB
      const getRes=await fetch(`${FIREBASE_URL}/db.json`);
      const currentDB=await getRes.json()||{};
      const currentOrders=currentDB.orders||[];

      // Add new order to orders array
      const updatedOrders=[order,...currentOrders];

      // Also update client record with latest name and address
      const currentClients=currentDB.clients||[];
      const normPhone=normalizePhone(phone);
      const clientExists=currentClients.find(c=>normalizePhone(c.phone)===normPhone||c.memberId===memberId);
      const updatedClients=clientExists
        ?currentClients.map(c=>(normalizePhone(c.phone)===normPhone||c.memberId===memberId)
          ?{...c,name:fullName,prefix,phone,gov,area,street,building,aptNum,floor,propType,lastOrder:Date.now()}
          :c)
        :[...currentClients,{id:"C-"+Date.now(),memberId:memberId||null,name:fullName,prefix,phone,gov,area,street,building,aptNum,floor,propType,joinedAt:Date.now(),lastOrder:Date.now(),totalOrders:0,totalSpent:0}];

      // Write back to DB
      const res=await fetch(`${FIREBASE_URL}/db.json`,{
        method:"PATCH",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({orders:updatedOrders,clients:updatedClients})
      });
      if(res.ok){
        saved=true;
        // Send WhatsApp notification to business
        const itemLines=Object.entries(items).filter(([,q])=>q>0).map(([id,q])=>{
          const p=products.find(x=>x.id===id);
          return p?`${p.name} × ${q} = ج.م ${p.price*q}`:"";
        }).filter(Boolean).join("\n");
        const waMsg=
`🐔 طلب جديد — دواجن كاكي
━━━━━━━━━━━━━━
👤 ${fullName}
🆔 ${memberId||"جديد"}
📞 ${phone}
${delivery==="delivery"?`📍 ${fullAddress}`:lang==="EN"?"🏪 Self Pickup":lang==="EN"?"🏪 Self Pickup":"🏪 استلام شخصي"}
━━━━━━━━━━━━━━
${itemLines}
━━━━━━━━━━━━━━
⚖️ السعر النهائي حسب الوزن عند الاستلام
💰 الإجمالي التقديري: ج.م ${total}`;
        window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(waMsg)}`,"_blank");
      }
    }catch(e){ saved=false; }

    if(!saved){
      // WhatsApp fallback
      const lines=Object.entries(items).filter(([,q])=>q>0).map(([id,q])=>{
        const p=products.find(x=>x.id===id);
        return p?`${p.name} × ${q} = ج.م ${p.price*q}`:"";
      }).filter(Boolean).join("\n");
      const msg=`🐔 طلب جديد — دواجن كاكي\n━━━━━━━━━━━━\n👤 ${fullName}\n📞 ${phone}\n📍 ${fullAddress}\n━━━━━━━━━━━━\n${lines}\n━━━━━━━━━━━━\n⚖️ السعر النهائي حسب الوزن عند الاستلام\n💰 الإجمالي التقديري: ج.م ${total}`;
      window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg)}`,"_blank");
    }

    setSending(false);
    setSent(true);
  };

  if(sent) return(
    <div style={{fontFamily:"'Cairo',sans-serif",background:BG,minHeight:"100vh",color:CREAM,direction:t.dir,maxWidth:400,margin:"0 auto",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24,textAlign:"center"}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;800;900&display=swap');*{box-sizing:border-box;margin:0;padding:0}body{background:#FFF8F0}`}</style>
      <div style={{fontSize:80,marginBottom:16}}>✅</div>
      <div style={{fontWeight:900,fontSize:22,color:GOLD,marginBottom:8}}>{t.sentTitle}</div>
      <div style={{fontSize:14,color:MUT,lineHeight:1.8,marginBottom:24}}>{t.sentSub}</div>
      <button onClick={()=>{setSent(false);setItems({});setNotes("");setStep(1);}}
        style={{background:GOLD,color:"#000",border:"none",borderRadius:14,padding:"13px 32px",fontWeight:800,fontSize:15,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
        {t.newOrder}
      </button>
    </div>
  );

  return(
    <div style={{fontFamily:"'Cairo',sans-serif",background:BG,minHeight:"100vh",color:CREAM,direction:t.dir,maxWidth:400,margin:"0 auto"}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap');*{box-sizing:border-box;margin:0;padding:0}body{background:#FFF8F0}input::placeholder,textarea::placeholder{color:#C4956A}select{font-family:'Cairo',sans-serif}select option{background:#fff;color:#3D1A00}::-webkit-scrollbar{display:none}`}</style>

      {/* Header */}
      <div style={{background:CARD,padding:"12px 18px",textAlign:"center",borderBottom:`2px solid ${GOLD}`,position:"sticky",top:0,zIndex:50,boxShadow:"0 2px 12px rgba(232,130,26,.12)"}}>
        {/* EN/AR Toggle */}
        <div style={{position:"absolute",top:14,right:14,display:"flex",alignItems:"center",gap:5}}>
          <span style={{fontSize:10,fontWeight:800,color:lang==="AR"?GOLD:MUT}}>AR</span>
          <div onClick={()=>setLang(l=>l==="AR"?"EN":"AR")}
            style={{width:42,height:24,borderRadius:12,background:lang==="EN"?GOLD:"#ddd",cursor:"pointer",position:"relative",transition:"background .3s",boxShadow:"0 1px 4px rgba(0,0,0,.15)"}}>
            <div style={{position:"absolute",top:3,left:lang==="EN"?20:3,width:18,height:18,borderRadius:"50%",background:"#fff",transition:"left .3s",boxShadow:"0 1px 4px rgba(0,0,0,.2)"}}/>
          </div>
          <span style={{fontSize:10,fontWeight:800,color:lang==="EN"?GOLD:MUT}}>EN</span>
        </div>
        <img src={LOGO_IMG} alt="KaKi" style={{width:80,height:80,objectFit:"contain",marginBottom:2}}/>
        <div style={{fontSize:11,color:MUT,marginTop:2}}>{t.subtitle}</div>
      </div>

      {/* Progress — new order: طلبك > بياناتك > عنوانك > تأكيد */}
      <div style={{display:"flex",padding:"10px 16px",gap:4,background:CARD,borderBottom:`1px solid ${BDR}`,direction:t.dir}}>
        {t.steps.map(([n,l],i)=>(
          <div key={i} style={{flex:1,textAlign:"center"}}>
            <div style={{width:24,height:24,borderRadius:"50%",background:step>i+1?GOLD:step===i+1?GOLD:BDR,color:step>=i+1?"#fff":MUT,fontWeight:800,fontSize:11,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 3px"}}>
              {step>i+1?"✓":n}
            </div>
            <div style={{fontSize:9,color:step===i+1?GOLD:MUT,fontWeight:step===i+1?700:400}}>{l}</div>
          </div>
        ))}
      </div>

      <div style={{padding:16,paddingBottom:100}}>

        {/* ══ STEP 1 — Order items (NEW FIRST STEP) ══ */}
        {step===1&&(
          <div>
            <div style={{fontWeight:800,fontSize:16,color:GOLD,marginBottom:4}}>{t.orderTitle}</div>
            <div style={{fontSize:12,color:MUT,marginBottom:16}}>{t.orderSub}</div>

            {errors.items&&(
              <div style={{background:"#ef444422",border:"1px solid #ef444466",borderRadius:10,padding:"10px 14px",marginBottom:12,fontSize:12,color:"#f87171",fontWeight:700}}>
                {t.itemsRequired}
              </div>
            )}

            <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:14}}>
              {products.map(p=>{
                const qty=items[p.id]||0;
                const isEnabled=p.enabled!==false; // default true
                return(
                  <div key={p.id} style={{background:CARD,borderRadius:14,padding:"12px 14px",border:`1px solid ${!isEnabled?"#e5e7eb":qty>0?GOLD:BDR}`,display:"flex",alignItems:"center",gap:12,opacity:isEnabled?1:0.55,position:"relative"}}>
                    {!isEnabled&&(
                      <div style={{position:"absolute",top:8,left:8,background:"#6b7280",color:"#fff",borderRadius:6,padding:"2px 7px",fontSize:10,fontWeight:700}}>
                        غير متاح حالياً
                      </div>
                    )}
                    {IMG_DATA[p.id]
  ? <img src={IMG_DATA[p.id]} alt={p.name} style={{width:64,height:64,objectFit:"cover",borderRadius:10,flexShrink:0,filter:isEnabled?"none":"grayscale(100%)"}}/>
  : <span style={{fontSize:32,flexShrink:0}}>{p.emoji}</span>}
                    <div style={{flex:1,minWidth:0}}>
                      <div style={{fontWeight:700,fontSize:13,color:isEnabled?DARK:MUT}}>{lang==="EN"?(p.nameEN||p.name):p.name}</div>
                      {p.byWeight
                        ?<div style={{fontSize:11,marginTop:2}}>
                           <div style={{color:isEnabled?GOLD:MUT,fontWeight:700,fontSize:12}}>{p.pricePerKg||CHICKEN_PRICE_PER_KG} {lang==="EN"?"EGP/kg":"ج.م/كج"}</div>
                           <div style={{fontSize:9,color:MUT,marginTop:2}}>⚖️ {lang==="EN"?"Final price based on weight upon delivery":"السعر النهائي حسب الوزن عند الاستلام"}</div>
                         </div>
                        :<div style={{fontSize:11,marginTop:2}}>
                           <div style={{color:isEnabled?GOLD:MUT,fontWeight:700,fontSize:12}}>{lang==="EN"?`${p.price} EGP/${p.unitEN||"kg"}`:`ج.م ${p.price} / ${p.unit||"كج"}`}</div>
                           <div style={{fontSize:9,color:MUT,marginTop:2}}>⚖️ {lang==="EN"?"Final price based on weight upon delivery":"السعر النهائي حسب الوزن عند الاستلام"}</div>
                         </div>
                      }
                    </div>
                    <div style={{display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
                      {qty>0&&isEnabled&&<button onClick={()=>rem(p.id)} style={{width:32,height:32,borderRadius:9,border:"none",background:LIGHT,color:CREAM,fontSize:18,cursor:"pointer",fontWeight:700}}>−</button>}
                      {qty>0&&isEnabled&&(
                        <div style={{textAlign:"center",minWidth:24}}>
                          <div style={{fontWeight:900,fontSize:16,color:GOLD}}>{qty}</div>
                          {p.qtyLabel&&<div style={{fontSize:9,color:MUT,marginTop:1}}>{p.qtyLabel}</div>}
                        </div>
                      )}
                      <button
                        disabled={!isEnabled}
                        onClick={()=>{if(isEnabled){add(p.id);setErrors(r=>({...r,items:false}));}}}
                        style={{width:32,height:32,borderRadius:9,border:"none",background:!isEnabled?"#e5e7eb":qty>0?GOLD:LIGHT,color:!isEnabled?"#9ca3af":qty>0?"#fff":DARK,fontSize:18,cursor:isEnabled?"pointer":"not-allowed",fontWeight:700}}>
                        +
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Total */}
            {total>0&&(
              <div style={{background:LIGHT,borderRadius:12,padding:"12px 16px",marginBottom:14,border:`1px solid ${BDR}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <div>
                  <div style={{fontWeight:700,fontSize:14,color:DARK}}>{t.totalLabel}</div>
                  <div style={{fontSize:10,color:MUT}}>{t.totalSub}</div>
                </div>
                <span style={{fontWeight:900,fontSize:20,color:GOLD}}>{lang==="EN"?`EGP ${total}`:`ج.م ${total}`}</span>
              </div>
            )}

            {/* Next → بياناتك */}
            <button onClick={()=>{if(validateStep3())setStep(2);}}
              style={{width:"100%",background:GOLD,color:"#000",border:"none",borderRadius:14,padding:"15px",fontWeight:900,fontSize:16,fontFamily:"'Cairo',sans-serif",cursor:"pointer",boxShadow:`0 8px 24px ${GOLD}44`}}>
              {t.nextBtn}
            </button>
          </div>
        )}
        {/* ══ STEP 2 — Personal Info (NEW SECOND STEP) ══ */}
        {step===2&&(
          <div>
            <div style={{fontWeight:800,fontSize:16,color:GOLD,marginBottom:4}}>{t.personalInfo}</div>
            <div style={{fontSize:12,color:MUT,marginBottom:16}}>{t.personalSub||"نحتاجها للتواصل معك"}</div>

            {/* Prefix */}
            <label style={lbl}>{t.prefixLabel}</label>
            <select style={{...inp(),marginBottom:10,cursor:"pointer"}} value={prefix} onChange={e=>setPrefix(e.target.value)}>
              <option value="">{t.prefixDef}</option>
              {t.prefixes.map(p=><option key={p} value={p}>{p}</option>)}
            </select>

            {/* Phone / Member ID */}
            <label style={lbl}>{t.phoneLabel}</label>
            <input style={{...inp("phone"),marginBottom:4}} placeholder={t.phonePH} type="text" value={phone}
              onChange={e=>{
                const v=e.target.value;
                const isMbr=v.toUpperCase().startsWith("MBR-");
                if(isMbr){setPhone(v);handleMemberId(v);}
                else{handlePhone(v);}
              }}/>
            {lookingUp&&<div style={{fontSize:11,color:MUT,marginBottom:6}}>{t.lookingUp}</div>}
            {!lookingUp&&errors.phone&&phone&&<div style={{fontSize:11,color:"#f87171",marginBottom:6}}>{t.phoneInvalid}</div>}
            {!lookingUp&&phone&&validatePhone(phone)&&<div style={{fontSize:11,color:"#2D7A3A",marginBottom:6}}>{t.phoneValid}</div>}
            {isExisting&&name&&<div style={{background:"#e8f5e9",borderRadius:10,padding:"8px 12px",marginBottom:8,fontSize:12,color:"#2D7A3A",fontWeight:700}}>{t.welcomeBack(name)}</div>}

            {/* Saved address for existing clients */}
            {isExisting&&(
              <div style={{background:LIGHT,borderRadius:10,padding:"10px 14px",marginBottom:10,border:`1px solid ${BDR}`}}>
                <div style={{fontSize:11,color:MUT,fontWeight:700,marginBottom:4}}>{t.savedAddress}</div>
                {gov&&area
                  ?<div style={{fontSize:13,color:DARK,fontWeight:600}}>{lang==="EN"?(t.govDisplayNames?.[gov]||gov):gov} — {lang==="EN"?(t.areaDisplayNames?.[area]||area):area}{street?" — "+street:""}</div>
                  :<div style={{fontSize:12,color:MUT}}>{t.noAddress}</div>
                }
                <button onClick={()=>setStep(3)} style={{background:"none",border:"none",color:GOLD,fontSize:11,fontFamily:"'Cairo',sans-serif",cursor:"pointer",padding:"4px 0",fontWeight:700}}>
                  {gov&&area?t.changeAddress:t.addAddress}
                </button>
              </div>
            )}
            {memberId&&(
              <div style={{background:LIGHT,borderRadius:10,padding:"10px 14px",marginBottom:10,border:`1px solid ${BDR}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <span style={{fontSize:12,color:MUT,fontWeight:700}}>{t.memberIdLabel}</span>
                <span style={{fontWeight:900,fontSize:16,color:DARK}}>{memberId}</span>
              </div>
            )}

            {/* Name */}
            <label style={lbl}>{t.nameLabel}</label>
            <input style={{...inp("name"),marginBottom:10}} placeholder={t.namePH} value={name}
              onChange={e=>{setName(e.target.value);setErrors(r=>({...r,name:false}));if(isExisting){setDataChanged(true);setDataSaved(false);}}}/>
            {errors.name&&<div style={{fontSize:11,color:"#f87171",marginBottom:8}}>{t.nameRequired}</div>}

            {/* Save/next button — 3 states */}
            {dataSaved&&<div style={{background:"#e8f5e9",borderRadius:10,padding:"8px 12px",marginBottom:8,fontSize:12,color:"#2D7A3A",fontWeight:700,textAlign:"center"}}>{t.dataSaved}</div>}

            {dataChanged&&!dataSaved
              ?<button onClick={saveClientData} disabled={saving}
                style={{width:"100%",background:saving?"#999":"#2D7A3A",color:"#fff",border:"none",borderRadius:14,padding:"15px",fontWeight:900,fontSize:15,fontFamily:"'Cairo',sans-serif",cursor:saving?"not-allowed":"pointer"}}>
                {saving?t.savingBtn:t.saveBtn}
              </button>
              :<button onClick={()=>{
                if(validateStep1()){
                  if(isExisting){setStep(4);}      // Existing → skip address → confirm
                  else if(delivery==="pickup"){setStep(4);}  // Pickup → confirm
                  else{setStep(3);}                 // New client + delivery → address
                }
              }}
                style={{width:"100%",background:GOLD,color:"#000",border:"none",borderRadius:14,padding:"15px",fontWeight:900,fontSize:16,fontFamily:"'Cairo',sans-serif",cursor:"pointer",boxShadow:`0 8px 24px ${GOLD}44`}}>
                {t.nextBtn}
              </button>
            }

            {/* Back to items */}
            <button onClick={()=>setStep(1)} style={{width:"100%",background:"none",border:"none",color:MUT,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer",marginTop:8,padding:6}}>
              {t.backBtn}
            </button>
          </div>
        )}
        {/* ══ STEP 3 — Address (NEW THIRD STEP) ══ */}
        {step===3&&(
          <div>
            <div style={{fontWeight:800,fontSize:16,color:GOLD,marginBottom:4}}>{t.addressTitle}</div>
            <div style={{fontSize:12,color:MUT,marginBottom:16}}>{t.addressSub}</div>

            {/* Location options */}
            <label style={lbl}>{t.locationLabel||"📍 الموقع (اختياري — اختر طريقة)"}</label>

            {/* Google Maps paste */}
            <div style={{background:CARD,border:`1px solid ${BDR}`,borderRadius:12,padding:"12px 14px",marginBottom:8}}>
              <div style={{fontSize:12,color:MUT,marginBottom:6,fontWeight:700}}>{t.pasteMap}</div>
              <div style={{display:"flex",gap:6}}>
                <input
                  style={{...inp(),marginBottom:0,flex:1,fontSize:12}}
                  placeholder="https://maps.google.com/..."
                  value={mapsLink}
                  onChange={e=>setMapsLink(e.target.value)}
                />
                {mapsLink&&(
                  <button onClick={()=>setMapsLink("")}
                    style={{background:LIGHT,border:"none",borderRadius:8,padding:"0 10px",color:MUT,cursor:"pointer",fontSize:13,flexShrink:0}}>✕</button>
                )}
              </div>
              {mapsLink&&<div style={{fontSize:11,color:"#10b981",marginTop:5,fontWeight:700}}>✅ تم إضافة رابط الموقع</div>}
            </div>

            {/* Map toggle */}
            <button onClick={()=>setMapOpen(o=>!o)}
              style={{width:"100%",background:locSet?`${SUCCESS}15`:CARD,border:`1.5px solid ${locSet?SUCCESS:BDR}`,borderRadius:12,padding:"13px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",marginBottom:10,fontFamily:"'Cairo',sans-serif",color:CREAM}}>
              <div style={{display:"flex",alignItems:"center",gap:10}}>
                <span style={{fontSize:22}}>🗺️</span>
                <div style={{textAlign:"right"}}>
                  <div style={{fontWeight:700,fontSize:13,color:locSet?SUCCESS:DARK}}>{locSet?"✅ تم تحديد الموقع على الخريطة":"تحديد الموقع على الخريطة"}</div>
                  <div style={{fontSize:10,color:MUT}}>اضغط لفتح الخريطة</div>
                </div>
              </div>
              <span style={{color:MUT}}>{mapOpen?"▲":"▼"}</span>
            </button>

            {/* Map */}
            {mapOpen&&(
              <div style={{marginBottom:10,borderRadius:12,overflow:"hidden",border:`1px solid ${BDR}`}}>
                <div id="client-map" style={{width:"100%",height:220}}/>
                <div style={{padding:"8px 10px",background:LIGHT,display:"flex",gap:8}}>
                  <button onClick={getUserLoc}
                    style={{flex:1,background:CARD,color:GOLD,border:`1px solid ${GOLD}`,borderRadius:8,padding:"9px",fontWeight:700,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
                    📍 موقعي الحالي
                  </button>
                  {locSet&&(
                    <button onClick={()=>setMapOpen(false)}
                      style={{flex:1,background:SUCCESS,color:"#fff",border:"none",borderRadius:8,padding:"9px",fontWeight:800,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
                      📍 هذا موقعي ✅
                    </button>
                  )}
                </div>
                <div style={{fontSize:10,color:MUT,textAlign:"center",padding:5,background:LIGHT}}>اضغط على الخريطة أو اسحب الـ Pin</div>
              </div>
            )}

            {/* Gov */}
            <label style={lbl}>المحافظة *</label>
            <div style={{display:"flex",gap:6,marginBottom:8}}>
              {Object.keys(AREAS).map(g=>(
                <button key={g} onClick={()=>{setGov(g===gov?"":g);setArea("");setCustomGov("");setErrors(r=>({...r,gov:false}));}}
                  style={{flex:1,background:gov===g?(GOV_COLORS[g]||GOLD):CARD,color:gov===g?"#fff":DARK,border:`1.5px solid ${errors.gov?ERROR:gov===g?(GOV_COLORS[g]||GOLD):BDR}`,borderRadius:10,padding:"10px 4px",fontWeight:700,fontSize:10,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
                  {lang==="EN"?(t.govDisplayNames?.[g]||g):g} {gov===g?"▲":"▼"}
                </button>
              ))}
            </div>

            {/* Area */}
            {gov&&!area&&(
              <>
                {gov==="أخرى"?(
                  <>
                    <label style={lbl}>{lang==="EN"?"Enter your area / district:":"اكتب منطقتك / حيّك:"}</label>
                    <input value={customGov}
                      onChange={e=>{setCustomGov(e.target.value);setArea(e.target.value.trim());if(e.target.value.trim())setErrors(r=>({...r,area:false}));}}
                      placeholder={lang==="EN"?"e.g. Alexandria — Sporting...":"مثال: طنطا — حي الشرق..."}
                      style={{width:"100%",boxSizing:"border-box",background:CARD,color:CREAM,border:`1px solid ${errors.area?"#ef4444":BDR}`,borderRadius:9,padding:"10px 12px",fontSize:13,fontFamily:"'Cairo',sans-serif",outline:"none",direction:"rtl",marginBottom:10}} />
                  </>
                ):(
                  <>
                    <label style={lbl}>{t.areaLabel}</label>
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,maxHeight:200,overflowY:"auto",marginBottom:10}}>
                      {AREAS[gov].map(a=>(
                        <button key={a} onClick={()=>{setArea(a);setErrors(r=>({...r,area:false}));}}
                          style={{background:CARD,color:CREAM,border:`1px solid ${errors.area?"#ef4444":BDR}`,borderRadius:9,padding:"9px 8px",fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer",textAlign:"center"}}>
                          {lang==="EN"?(t.areaDisplayNames?.[a]||a):a}
                        </button>
                      ))}
                    </div>
                  </>
                )}
              </>
            )}
            {gov&&area&&(
              <button onClick={()=>{setArea("");if(gov==="أخرى")setCustomGov("");}}
                style={{width:"100%",background:GOV_COLORS[gov]||GOLD,color:"#000",border:"none",borderRadius:10,padding:"11px 14px",fontWeight:800,fontSize:13,fontFamily:"'Cairo',sans-serif",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
                <span>📍 {gov==="أخرى"?customGov:(lang==="EN"?(t.govDisplayNames?.[gov]||gov):gov)} — {lang==="EN"?(t.areaDisplayNames?.[area]||area):area}</span>
                <span style={{fontSize:11,fontWeight:400}}>{t.changeBtn}</span>
              </button>
            )}

            {/* Property type */}
            {area&&(
              <>
                <div style={{display:"flex",gap:8,marginBottom:10}}>
                  {[{id:"apt",label:t.aptType,icon:"🏢"},{id:"house",label:t.villaType,icon:"🏠"}].map(pt=>(
                    <button key={pt.id} onClick={()=>{setPropType(pt.id);setIsCompound(false);}}
                      style={{flex:1,background:propType===pt.id?GOLD:CARD,color:propType===pt.id?"#fff":DARK,border:`1.5px solid ${propType===pt.id?GOLD:BDR}`,borderRadius:24,padding:"10px 6px",fontWeight:propType===pt.id?800:400,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:5}}>
                      {pt.icon} {pt.label}
                    </button>
                  ))}
                </div>

                {/* Compound checkbox */}
                <button onClick={()=>setIsCompound(c=>!c)}
                  style={{width:"100%",background:isCompound?`${GOLD}15`:CARD,border:`1.5px solid ${isCompound?GOLD:BDR}`,borderRadius:10,padding:"10px 14px",display:"flex",alignItems:"center",gap:10,marginBottom:10,cursor:"pointer",fontFamily:"'Cairo',sans-serif"}}>
                  <div style={{width:20,height:20,borderRadius:5,border:`2px solid ${isCompound?GOLD:BDR}`,background:isCompound?GOLD:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    {isCompound&&<span style={{color:"#fff",fontSize:13,fontWeight:900}}>✓</span>}
                  </div>
                  <div style={{textAlign:"right"}}>
                    <div style={{fontWeight:700,fontSize:13,color:isCompound?GOLD:DARK}}>{t.compoundLabel}</div>
                    <div style={{fontSize:10,color:MUT}}>{t.compoundSub}</div>
                  </div>
                </button>

                {/* Compound name — required when checked */}
                {isCompound&&(
                  <div style={{marginBottom:10}}>
                    <label style={lbl}>{t.compoundNameLabel||"اسم الكومباوند *"}</label>
                    <input
                      style={{...inp("compoundName"),marginBottom:4}}
                      placeholder={t.compoundNamePH||"مثال: كومباوند بالم هيلز"}
                      value={compoundName}
                      onChange={e=>{setCompoundName(e.target.value);setErrors(r=>({...r,compoundName:false}));}}
                    />
                    {errors.compoundName&&<div style={{fontSize:11,color:"#f87171",marginBottom:6}}>{t.compoundNameRequired||"⚠️ اكتب اسم الكومباوند"}</div>}
                  </div>
                )}

                <label style={lbl}>{t.buildingLabel}</label>
                <input style={{...inp("building"),marginBottom:10}} placeholder="مثال: ٥" value={building} onChange={e=>{setBuilding(e.target.value);setErrors(r=>({...r,building:false}));}}/>

                <div style={{display:"flex",gap:8,marginBottom:10}}>
                  <div style={{flex:1}}>
                    <label style={lbl}>{propType==="house"?t.villaLabel:t.aptLabel}</label>
                    <input style={inp("aptNum")} placeholder="٣" value={aptNum} onChange={e=>{setAptNum(e.target.value);setErrors(r=>({...r,aptNum:false}));}}/>
                  </div>
                  {propType==="apt"&&(
                    <div style={{flex:1}}>
                      <label style={lbl}>{t.floorLabel}</label>
                      <select style={{...inp(),marginBottom:0,cursor:"pointer"}} value={floor} onChange={e=>setFloor(e.target.value)}>
                        <option value="">اختر</option>
                        {t.floors.map(f=>(
                          <option key={f} value={f}>{f}</option>
                        ))}
                      </select>
                    </div>
                  )}
                </div>

                <label style={lbl}>الشارع {isCompound?`(${lang==="EN"?"optional":"اختياري"})`:"*"}</label>
                <input style={{...inp(isCompound?"":  "street"),marginBottom:10}} placeholder="مثال: شارع الجمهورية" value={street} onChange={e=>{setStreet(e.target.value);setErrors(r=>({...r,street:false}));}}/>
                {/* Delivery notes */}
                <label style={lbl}>📝 ملاحظات التوصيل (اختياري)</label>
                <input style={{...inp(),marginBottom:10}} placeholder="مثال: بوابة ٤ — جنب المسجد — أمام المدرسة" value={extra} onChange={e=>setExtra(e.target.value)}/>
              </>
            )}

            {/* Validation errors */}
            {(errors.gov||errors.area||errors.building||errors.aptNum||errors.street)&&(
              <div style={{background:"#ef444422",border:"1px solid #ef444466",borderRadius:10,padding:"10px 14px",marginBottom:12,fontSize:12,color:"#f87171",fontWeight:700}}>
                ⚠️ من فضلك اكمل الحقول المطلوبة
              </div>
            )}

            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>setStep(2)}
                style={{flex:1,background:LIGHT,color:CREAM,border:"none",borderRadius:14,padding:"14px",fontWeight:700,fontSize:14,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
                {t.backBtn}
              </button>
              <button onClick={()=>{if(validateStep2())setStep(4);}}
                style={{flex:2,background:GOLD,color:"#000",border:"none",borderRadius:14,padding:"14px",fontWeight:900,fontSize:15,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
                التالي ←
              </button>
            </div>
          </div>
        )}

        {/* ══ STEP 4 — Confirm ══ */}
        {step===4&&(
          <div>
            <div style={{fontWeight:800,fontSize:16,color:GOLD,marginBottom:4}}>{t.confirmTitle}</div>
            <div style={{fontSize:12,color:MUT,marginBottom:16}}>{t.confirmSub}</div>

            {/* Summary */}
            <div style={{background:CARD,borderRadius:14,padding:"14px 16px",marginBottom:10,border:`1px solid ${BDR}`}}>
              <div style={{fontWeight:700,fontSize:13,color:GOLD,marginBottom:10}}>{t.yourDataLabel}</div>
              <div style={{fontSize:13,color:CREAM,lineHeight:2}}>
                <div>👤 {prefix?prefix+" ":""}{name}</div>
                <div>📞 {phone}</div>
                <div>{delivery==="pickup"?"🏪 استلام شخصي":lang==="EN"?`🚚 Delivery — ${gov==="أخرى"?customGov:(t.govDisplayNames?.[gov]||gov)} — ${t.areaDisplayNames?.[area]||area}`:`🛵 توصيل — ${gov==="أخرى"?customGov:gov} — ${area}`}</div>
                {delivery==="delivery"&&<div style={{fontSize:12,color:MUT}}>{street} — {building} ش{aptNum}{floor?" د"+floor:""}</div>}
                {extra&&<div style={{fontSize:12,color:MUT}}>📝 {extra}</div>}
                {mapsLink&&<div style={{fontSize:11,color:"#10b981"}}>{lang==="EN"?"🔗 Google Maps link added ✅":"🔗 رابط Google Maps مضاف ✅"}</div>}
                {locSet&&<div style={{fontSize:11,color:"#10b981"}}>{lang==="EN"?"📍 Location set on map ✅":"📍 الموقع محدد على الخريطة ✅"}</div>}
              </div>
              <button onClick={()=>setStep(1)} style={{background:"none",border:"none",color:GOLD,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer",marginTop:6}}>{t.editBtn}</button>
            </div>

            <div style={{background:CARD,borderRadius:14,padding:"14px 16px",marginBottom:14,border:`1px solid ${BDR}`}}>
              <div style={{fontWeight:700,fontSize:13,color:GOLD,marginBottom:10}}>{t.yourItemsLabel}</div>
              {products.filter(p=>items[p.id]>0).map(p=>(
                <div key={p.id} style={{display:"flex",alignItems:"center",gap:10,padding:"8px 0",borderBottom:`1px solid ${BDR}`}}>
                  {IMG_DATA[p.id]
                    ?<img src={IMG_DATA[p.id]} alt={p.name} style={{width:44,height:44,objectFit:"cover",borderRadius:8,flexShrink:0}}/>
                    :<span style={{fontSize:24,flexShrink:0}}>{p.emoji}</span>}
                  <div style={{flex:1}}>
                    <div style={{fontSize:12,fontWeight:700,color:DARK}}>{lang==="EN"?(p.nameEN||p.name):p.name}</div>
                    <div style={{fontSize:11,color:MUT}}>× {items[p.id]} {lang==="EN"?(p.unitEN||"kg"):(p.unit||"كج")}</div>
                  </div>
                  <span style={{color:GOLD,fontWeight:700,fontSize:13}}>{lang==="EN"?`EGP ${Math.round((p.byWeight?Math.round((p.pricePerKg||CHICKEN_PRICE_PER_KG)*CHICKEN_AVG_WEIGHT):p.price)*items[p.id])}`:`ج.م ${Math.round((p.byWeight?Math.round((p.pricePerKg||CHICKEN_PRICE_PER_KG)*CHICKEN_AVG_WEIGHT):p.price)*items[p.id])}`}</span>
                </div>
              ))}
              <div style={{display:"flex",justifyContent:"space-between",marginTop:10,fontWeight:900,fontSize:16}}>
                <div style={{textAlign:"right"}}>
                  <div style={{fontWeight:900,fontSize:16,color:DARK}}>{t.totalLabel}</div>
                  <div style={{fontSize:10,color:MUT}}>{t.totalSub}</div>
                </div>
                <span style={{color:GOLD}}>ج.م {total}</span>
              </div>
              <button onClick={()=>setStep(3)} style={{background:"none",border:"none",color:GOLD,fontSize:12,fontFamily:"'Cairo',sans-serif",cursor:"pointer",marginTop:6}}>{t.editBtn}</button>
            </div>

            {notes&&(
              <div style={{background:CARD,borderRadius:12,padding:"10px 14px",marginBottom:14,border:`1px solid ${BDR}`,fontSize:12,color:MUT}}>
                📝 {notes}
              </div>
            )}

            <button onClick={sendOrder} disabled={sending}
              style={{width:"100%",background:sending?"#C8A060":GOLD,color:"#fff",border:"none",borderRadius:16,padding:"16px",fontWeight:900,fontSize:16,fontFamily:"'Cairo',sans-serif",cursor:sending?"not-allowed":"pointer",boxShadow:`0 8px 32px ${GOLD}44`,marginBottom:8}}>
              {sending?t.sendingBtn:t.sendBtn}
            </button>
            <button onClick={()=>setStep(isExisting?2:3)}
              style={{width:"100%",background:LIGHT,color:DARK,border:`1px solid ${BDR}`,borderRadius:14,padding:"12px",fontWeight:600,fontSize:13,fontFamily:"'Cairo',sans-serif",cursor:"pointer"}}>
              {t.backBtn}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
